// module.yaml files are converted to JSON by the `leakzero-module-yaml` plugin (vite.config.ts).
declare module '*.yaml' {
  const value: unknown;
  export default value;
}

// Generated by the same plugin: the Lucide icons named by the module declarations, keyed by YAML name.
declare module 'virtual:leakzero-module-icons' {
  import type { LucideIcon } from 'lucide-react';
  const icons: Record<string, LucideIcon>;
  export default icons;
}
